# ---------------------------------------------------------------------------
# Test 1: All Places calls refused with REQUEST_DENIED
# ---------------------------------------------------------------------------


class TestAllPlacesRefused:
    """
    When every Places call returns REQUEST_DENIED, the service must NOT
    report success. The current code returns True and stores "not_found",
    which is the bug.
    """

    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_targets_config"
    )
    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_preset_defs"
    )
    @patch("services.property_travel_service.get_cached_enrichment_data")
    @patch("services.property_travel_service.request_with_retries")
    def test_returns_false_when_all_places_denied(
        self, mock_request, mock_cache, mock_preset_defs, mock_travel_config, app, prop
    ):
        """
        ASSERT: calculate_for_property() returns False when Places is REQUEST_DENIED.
        FAILS TODAY: current code returns True.
        """
        mock_cache.return_value = None
        mock_preset_defs.return_value = FAKE_PRESET_DEFS
        mock_travel_config.return_value = FAKE_TRAVEL_CONFIG

        # Every network call returns REQUEST_DENIED
        mock_request.return_value = _places_denied_response()

        from services.property_travel_service import PropertyTravelService

        svc = PropertyTravelService(
            google_maps_key="FAKE_MAPS_KEY", google_places_key="FAKE_KEY"
        )
        svc.location_service = MagicMock()
        svc.location_service.ensure_coordinates.return_value = True

        result = svc.calculate_for_property(prop, commit=True)

        # The fix must make this False — the service should not claim success
        # when every API call was refused.
        assert result is False, (
            "calculate_for_property() returned True even though every Places "
            "call was REQUEST_DENIED. It must return False to signal failure."
        )

    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_targets_config"
    )
    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_preset_defs"
    )
    @patch("services.property_travel_service.get_cached_enrichment_data")
    @patch("services.property_travel_service.request_with_retries")
    def test_travel_json_distinguishes_denied_from_not_found(
        self, mock_request, mock_cache, mock_preset_defs, mock_travel_config, app, prop
    ):
        """
        ASSERT: The stored travel JSON must NOT use status="not_found" when
        the API refused the request. It should use a distinct error status.
        FAILS TODAY: current code stores "not_found" for both cases.
        """
        mock_cache.return_value = None
        mock_preset_defs.return_value = FAKE_PRESET_DEFS
        mock_travel_config.return_value = FAKE_TRAVEL_CONFIG

        mock_request.return_value = _places_denied_response()

        from services.property_travel_service import PropertyTravelService

        svc = PropertyTravelService(
            google_maps_key="FAKE_MAPS_KEY", google_places_key="FAKE_KEY"
        )
        svc.location_service = MagicMock()
        svc.location_service.ensure_coordinates.return_value = True

        svc.calculate_for_property(prop, commit=True)

        # Reload from DB to see what was persisted
        db.session.refresh(prop)
        travel = prop.travel

        # The status must NOT be "not_found": the API never searched, it refused.
        assert_every_target_reports_a_refusal(
            travel, "every Places call REQUEST_DENIED"
        )


