# ---------------------------------------------------------------------------
# Test 6: Missing API key — load-bearing because it's a configuration error,
#          not a runtime API failure. The current code uses "no_places_key"
#          which is at least distinguishable, but the method still returns True.
# ---------------------------------------------------------------------------


class TestMissingAPIKey:
    """
    When no API key is configured, the service cannot possibly succeed.
    It must return False. The current code returns True with status
    "no_places_key" — the status is arguably fine, but returning True
    is the bug.
    """

    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_targets_config"
    )
    @patch(
        "services.property_travel_service.SearchProfileService.get_travel_preset_defs"
    )
    @patch("services.property_travel_service.get_cached_enrichment_data")
    @patch("services.property_travel_service.request_with_retries")
    def test_missing_key_returns_false(
        self, mock_request, mock_cache, mock_preset_defs, mock_travel_config, app, prop
    ):
        """
        ASSERT: No API key → method returns False.
        FAILS TODAY: returns True.
        """
        mock_cache.return_value = None
        mock_preset_defs.return_value = FAKE_PRESET_DEFS
        mock_travel_config.return_value = FAKE_TRAVEL_CONFIG

        from services.property_travel_service import PropertyTravelService

        # Explicitly pass empty/None key
        svc = PropertyTravelService(google_places_key="")
